public enum IrohError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {



    case InvalidArgument(detail: String
    )
    case EndpointClosed
    case Cancelled
    case Transport(detail: String
    )
    case StreamReset(code: Int64
    )
    case StreamStopped(code: Int64
    )






    public var errorDescription: String? {
        String(reflecting: self)
    }

}

#if compiler(>=6)
extension IrohError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeIrohError: FfiConverterRustBuffer {
    typealias SwiftType = IrohError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> IrohError {
        let variant: Int32 = try readInt(&buf)
        switch variant {




        case 1: return .InvalidArgument(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .EndpointClosed
        case 3: return .Cancelled
        case 4: return .Transport(
            detail: try FfiConverterString.read(from: &buf)
            )
        case 5: return .StreamReset(
            code: try FfiConverterInt64.read(from: &buf)
            )
        case 6: return .StreamStopped(
            code: try FfiConverterInt64.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

